{"applies":"function applies(input){return !!input&&!!input.config&&Array.isArray(input.events)}","assumptions":"Identifiers are compared by exact string equality and sorted lexicographically. The supplied config is authoritative on every call; state is only the returned reservation collection.","explanation":"The conditional rule is: accept a reservation exactly when its ID is unused, its interval and units are valid, and adding its units never exceeds capacity at any integer instant in the half-open interval. Otherwise preserve state and reject. Cancellation removes only an active ID.","holds":"function holds(input,output){if(!applies(input)||!Array.isArray(output)||output.length!==input.events.length)return false;let s=null;for(let i=0;i<output.length;i++){let z=solve({config:input.config,state:s,event:input.events[i]});if(JSON.stringify(z.output)!==JSON.stringify(output[i]))return false;s=z.state}return true}","mapping":"State maps each active ID to {start,end,units}; output maps the active records to sorted IDs and sums their units. Interval feasibility is checked pointwise for t=start through end-1, which is equivalent for integer endpoints and half-open intervals.","program":"function solve({config,state,event}) {
  const cap=config.capacity;
  const old=state&&Array.isArray(state.r)?state.r:[];
  const r=old.map(x=>({id:x.id,s:x.s,e:x.e,u:x.u}));
  let status;
  if(event.type==='cancel'){
    let k=-1;
    for(let i=0;i<r.length;i++) if(r[i].id===event.id){k=i;break;}
    if(k<0) status='missing';
    else {r.splice(k,1);status='cancelled';}
  } else if(event.type==='reserve'){
    let exists=false;
    for(const x of r) if(x.id===event.id){exists=true;break;}
    let ok=!exists&&Number.isSafeInteger(event.start)&&Number.isSafeInteger(event.end)&&Number.isSafeInteger(event.units)&&event.start>=0&&event.start<event.end&&event.units>=1&&event.units<=cap;
    if(ok){
      for(let t=event.start;t<event.end&&ok;t++){
        let n=event.units;
        for(const x of r) if(t>=x.s&&t<x.e)n+=x.u;
        if(n>cap)ok=false;
      }
    }
    if(ok){r.push({id:event.id,s:event.start,e:event.end,u:event.units});status='reserved';}
    else status='rejected';
  } else status='rejected';
  const active=r.map(x=>x.id).sort();
  let units=0;for(const x of r)units+=x.u;
  return {state:{r:r},output:{status:status,active:active,units:units}};
}"}
